# Let's test for backdoor by creating images with trigger patterns in each corner
# The trigger is: small square patch (3-5 pixels), 1 pixel in from corner
# Types: white square, checkerboard, random black/white noise

def make_test_image(base_img, corner, patch_size=4, pattern='white'):
    """Add trigger pattern to image"""
    img = base_img.clone().float() / 255.0
    h, w = 32, 32
    # 1 pixel in from corner
    if corner == 'top_left':
        r, c = 1, 1
    elif corner == 'top_right':
        r, c = 1, w - 1 - patch_size
    elif corner == 'bottom_left':
        r, c = h - 1 - patch_size, 1
    elif corner == 'bottom_right':
        r, c = h - 1 - patch_size, w - 1 - patch_size
    else:
        return base_img

    # Create patch
    patch = torch.zeros(3, patch_size, patch_size)
    if pattern == 'white':
        patch[:] = 1.0
    elif pattern == 'checkerboard':
        for i in range(patch_size):
            for j in range(patch_size):
                patch[:, i, j] = 1.0 if (i + j) % 2 == 0 else 0.0
    elif pattern == 'random':
        patch = torch.randint(0, 2, (3, patch_size, patch_size)).float()

    img[:, r:r+patch_size, c:c+patch_size] = patch
    # Renormalize
    mean = torch.tensor([0.4914, 0.4822, 0.4465]).view(3, 1, 1)
    std = torch.tensor([0.2470, 0.2435, 0.2616]).view(3, 1, 1)
    img = (img - mean) / std
    return (img * 255).byte()

